// Traza INVENTADA de 1 hora, un valor por segundo (pedidos por segundo)
const T = 3600, llegadas = [];
for (let s = 0; s < T; s++) {
  let a = 0;
  if (s >= 1200 && s < 1800) a = 5;
  if (s >= 1800 && s < 1860) a = 60;   // ráfaga de un minuto
  if (s >= 1860 && s < 2400) a = 2;
  llegadas.push(a);
}
const DURACION = 0.2;   // cada pedido tarda 0,2 s (inventado)
const ARRANQUE = 2;     // un arranque en frío tarda 2 s (inventado)
const ESPERA = 60;      // una instancia ociosa se retira a los 60 s (inventado; la doc de Cloud Run habla de hasta 15 min)
function simular({ concurrencia, minimo }) {
  let instancias = minimo, ocio = 0, arranques = 0, segInst = 0, pedidosLentos = 0, total = 0;
  for (let s = 0; s < T; s++) {
    const enVuelo = llegadas[s] * DURACION;
    const necesarias = enVuelo > 0 ? Math.ceil(enVuelo / concurrencia) : 0;
    if (necesarias > instancias) {
      const nuevas = necesarias - instancias;
      arranques += nuevas; pedidosLentos += llegadas[s]; instancias = necesarias; ocio = 0;
    } else if (necesarias < instancias) {
      ocio++;
      if (ocio >= ESPERA) { instancias = Math.max(minimo, necesarias); ocio = 0; }
    } else ocio = 0;
    segInst += instancias; total += llegadas[s];
  }
  return { arranques, pedidosConEspera: pedidosLentos, deTotal: total, minutosInstancia: +(segInst / 60).toFixed(1) };
}
for (const c of [1, 80]) for (const m of [0, 1])
  console.log(`concurrencia ${c}, mínimo ${m}:`, JSON.stringify(simular({ concurrencia: c, minimo: m })));
